import{_ as t,a0 as l,w as o,s as d,ao as r,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"更深入地瞭解 Linux 權限 | LCTT x X-CMD","titleTemplate":false,"description":"更深入地瞭解 Linux 權限 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"更深入地瞭解 Linux 權限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"更深入地瞭解 Linux 權限 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190527 A deeper dive into Linux permissions","title":"更深入地瞭解 Linux 權限","tag":"201906","desc":""},"relativePath":"201906/20190527 A deeper dive into Linux permissions.md","filePath":"[post].md"}'),c={name:"201906/20190527 A deeper dive into Linux permissions.md"};function h(g,s,u,k,b,f){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="更深入地瞭解-linux-權限" tabindex="-1">更深入地瞭解 Linux 權限 <a class="header-anchor" href="#更深入地瞭解-linux-權限" aria-label="Permalink to “更深入地瞭解 Linux 權限”">​</a></h1><blockquote><p>在 Linux 上查看文件權限時，有時你會看到的不僅僅是普通的 r、w、x 和 -。如何更清晰地瞭解這些字符試圖告訴你什麼以及這些權限如何工作？</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201906/07/150718q09wnve6ne6v9063.jpg" alt="Sandra Henry-Stocker"></p><p>在 Linux 上查看文件權限時，有時你會看到的不僅僅是普通的 <code>r</code>、<code>w</code>、<code>x</code> 和 <code>-</code>。除了在所有者、組和其他中看到 <code>rwx</code> 之外，你可能會看到 <code>s</code> 或者 <code>t</code>，如下例所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxrwsrwt</span></span></code></pre></div><p>要進一步明確的方法之一是使用 <code>stat</code> 命令查看權限。<code>stat</code> 的第四行輸出以八進制和字符串格式顯示文件權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stat /var/mail</span></span>
<span class="line"><span>  File: /var/mail</span></span>
<span class="line"><span>  Size: 4096            Blocks: 8          IO Block: 4096   directory</span></span>
<span class="line"><span>Device: 801h/2049d      Inode: 1048833     Links: 2</span></span>
<span class="line"><span>Access: (3777/drwxrwsrwt)  Uid: (    0/    root)   Gid: (    8/    mail)</span></span>
<span class="line"><span>Access: 2019-05-21 19:23:15.769746004 -0400</span></span>
<span class="line"><span>Modify: 2019-05-21 19:03:48.226656344 -0400</span></span>
<span class="line"><span>Change: 2019-05-21 19:03:48.226656344 -0400</span></span>
<span class="line"><span> Birth: -</span></span></code></pre></div><p>這個輸出提示我們，分配給文件權限的位數超過 9 位。事實上，有 12 位。這些額外的三位提供了一種分配超出通常的讀、寫和執行權限的方法 - 例如，<code>3777</code>（二進制 <code>011111111111</code>）表示使用了兩個額外的設置。</p><p>該值的第一個 <code>1</code> （第二位）表示 SGID（設置 GID），為運行文件而賦予臨時權限，或以該關聯組的權限來使用目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>011111111111</span></span>
<span class="line"><span> ^</span></span></code></pre></div><p>SGID 將正在使用該文件的用户作為該組成員之一而分配臨時權限。</p><p>第二個 <code>1</code>（第三位）是“粘連”位。它確保<em>只有</em>文件的所有者能夠刪除或重命名該文件或目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>011111111111</span></span>
<span class="line"><span>  ^</span></span></code></pre></div><p>如果權限是 <code>7777</code> 而不是 <code>3777</code>，我們知道 SUID（設置 UID）字段也已設置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>111111111111</span></span>
<span class="line"><span>^</span></span></code></pre></div><p>SUID 將正在使用該文件的用户作為文件擁有者分配臨時權限。</p><p>至於我們上面看到的 <code>/var/mail</code> 目錄，所有用户都需要訪問，因此需要一些特殊值來提供它。</p><p>但現在讓我們更進一步。</p><p>特殊權限位的一個常見用法是使用 <code>passwd</code> 之類的命令。如果查看 <code>/usr/bin/passwd</code> 文件，你會注意到 SUID 位已設置，它允許你更改密碼（以及 <code>/etc/shadow</code> 文件的內容），即使你是以普通（非特權）用户身份運行，並且對此文件沒有讀取或寫入權限。當然，<code>passwd</code> 命令很聰明，不允許你更改其他人的密碼，除非你是以 root 身份運行或使用 <code>sudo</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /usr/bin/passwd</span></span>
<span class="line"><span>-rwsr-xr-x 1 root root 63736 Mar 22 14:32 /usr/bin/passwd</span></span>
<span class="line"><span>$ ls -l /etc/shadow</span></span>
<span class="line"><span>-rw-r----- 1 root shadow 2195 Apr 22 10:46 /etc/shadow</span></span></code></pre></div><p>現在，讓我們看一下使用這些特殊權限可以做些什麼。</p><h3 id="如何分配特殊文件權限" tabindex="-1">如何分配特殊文件權限 <a class="header-anchor" href="#如何分配特殊文件權限" aria-label="Permalink to “如何分配特殊文件權限”">​</a></h3><p>與 Linux 命令列中的許多東西一樣，你可以有不同的方法設置。 <code>chmod</code> 命令允許你以數字方式或使用字符表達式更改權限。</p><p>要以數字方式更改文件權限，你可以使用這樣的命令來設置 SUID 和 SGID 位：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 6775 tryme</span></span></code></pre></div><p>或者你可以使用這樣的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod ug+s tryme &lt;== 用於 SUID 和 SGID 權限</span></span></code></pre></div><p>如果你要添加特殊權限的文件是腳本，你可能會對它不符合你的期望感到驚訝。這是一個非常簡單的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat tryme</span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo I am $USER</span></span></code></pre></div><p>即使設置了 SUID 和 SGID 位，並且 root 是文件所有者，運行腳本也不會產生你可能期望的 “I am root”。為什麼？因為 Linux 會忽略腳本的 SUID 和 SGID 位。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l tryme</span></span>
<span class="line"><span>-rwsrwsrwt 1 root root 29 May 26 12:22 tryme</span></span>
<span class="line"><span>$ ./tryme</span></span>
<span class="line"><span>I am jdoe</span></span></code></pre></div><p>另一方面，如果你對一個編譯的程序之類進行類似的嘗試，就像下面這個簡單的 C 程序一樣，你會看到不同的效果。在此示例程序中，我們提示用户輸入文件名並創建它，並給文件寫入權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    FILE *fp;   /* file pointer*/</span></span>
<span class="line"><span>    char fName[20];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    printf(&quot;Enter the name of file to be created: &quot;);</span></span>
<span class="line"><span>    scanf(&quot;%s&quot;,fName);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /* create the file with write permission */</span></span>
<span class="line"><span>    fp=fopen(fName,&quot;w&quot;);</span></span>
<span class="line"><span>    /* check if file was created */</span></span>
<span class="line"><span>    if(fp==NULL)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        printf(&quot;File not created&quot;);</span></span>
<span class="line"><span>        exit(0);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    printf(&quot;File created successfully\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>編譯程序並運行該命令以使 root 用户成為所有者並設置所需權限後，你將看到它以預期的 root 權限運行 - 留下新創建的 root 為所有者的文件。當然，你必須具有 <code>sudo</code> 權限才能運行一些需要的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cc -o mkfile mkfile.c            &lt;== 編譯程序</span></span>
<span class="line"><span>$ sudo chown root:root mkfile       &lt;== 更改所有者和組為 “root”</span></span>
<span class="line"><span>$ sudo chmod ug+s mkfile        &lt;== 添加 SUID and SGID 權限</span></span>
<span class="line"><span>$ ./mkfile              &lt;== 運行程序</span></span>
<span class="line"><span>Enter name of file to be create: empty</span></span>
<span class="line"><span>File created successfully</span></span>
<span class="line"><span>$ ls -l empty</span></span>
<span class="line"><span>-rw-rw-r-- 1 root root 0 May 26 13:15 empty</span></span></code></pre></div><p>請注意，文件所有者是 root - 如果程序未以 root 權限運行，則不會發生這種情況。</p><p>權限字符串中不常見設置的位置（例如，rw<strong>s</strong>rw<strong>s</strong>rw<strong>t</strong>）可以幫助提醒我們每個位的含義。至少第一個 “s”（SUID） 位於所有者權限區域中，第二個 （SGID） 位於組權限區域中。為什麼粘連位是 “t” 而不是 “s” 超出了我的理解。也許創造者想把它稱為 “tacky bit”，但由於這個詞的不太令人喜歡的第二個定義而改變了他們的想法。無論如何，額外的權限設置為 Linux 和其他 Unix 系統提供了許多額外的功能。</p><hr>`,38)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3397790/a-deeper-dive-into-linux-permissions.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3397790/a-deeper-dive-into-linux-permissions.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const w=t(c,[["render",h]]);export{y as __pageData,w as default};
